import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const reflectLimitScenarios={'reflect-limit-mirror':'a2-p11-r1c3','reflect-limit-god':'a2-p17-r3c2'} as const;
export type ReflectLimitScenario=keyof typeof reflectLimitScenarios;
export function isReflectLimitScenario(name:string):name is ReflectLimitScenario{return Object.hasOwn(reflectLimitScenarios,name);}
export function makeReflectLimitScenario(name:ReflectLimitScenario,players:{id:string;name:string}[],options:{school?:'magic'|'warrior';bonus?:number;level?:number;owner?:string;prohibited?:boolean}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string],school=options.school??'magic',bonus=options.bonus??0,level=options.level??5;
 assignCharacter(s,a,options.prohibited?'吟遊詩人のレスター':'侍大将のシン');assignCharacter(s,b,options.owner??'聖騎士ランスロット');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,b);s.players[b]!.permanent={endurance:100,warrior_level:20+level-stats.warrior_level,magic_level:20+level-stats.magic_level,spirit:20+6-stats.spirit};
 const attack=takeCard(s,a,options.prohibited?'呪歌':school==='magic'?'炎舞':'黒翼飛翔剣'),defense=takeCard(s,b,reflectLimitScenarios[name]),prayer=takeCard(s,bonus?a:b,'必勝の祈り'),fate=takeCard(s,c,'命運凶変');trimHand(s,a,attack,...(bonus?[prayer]:[]));trimHand(s,b,defense,...(!bonus?[prayer]:[]));trimHand(s,c,fate);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(bonus||1)},r=transition(s,input,e);if(!r.ok)throw Error(`REFLECT_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('REFLECT_FIXTURE_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('REFLECT_FIXTURE_IDS');}
 let boosted=false;for(const p of players)act(p.id,{type:'PASS_SETUP'});act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'ATTACK',cardInstanceId:attack,targetIds:[b],dedicated:!!options.prohibited});for(let n=0;n<300;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;if(bonus&&!boosted&&w.kind==='effect-level'){act(a,{type:'PLAY_REACTION',cardInstanceId:prayer,mode:'effect-plus',targetActionId:w.continuation.id});boosted=true;}else act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('REFLECT_FIXTURE_WINDOW');
}
